import numpy as np
from scipy.optimize import least_squares
TL=T*np.log(T); V=np.var(sigma)
G={
 'log(1+k eps)': lambda k: np.log(1+k*eps),
 'eps/(1+k eps)': lambda k: eps/(1+k*eps),
 'tanh(k eps)': lambda k: np.tanh(k*eps),
 'eps^k/(1+eps^k)': lambda k: eps**k/(1+eps**k),
 'sqrt(1+k eps)': lambda k: np.sqrt(1+k*eps),
 'eps^k': lambda k: eps**k,
 '(1-exp(-k eps))^2': lambda k: (1-np.exp(-k*eps))**2,
}
H={
 'T^q': lambda q: T**q,
 'exp(-q/T)': lambda q: np.exp(-q/T),
 'exp(q T)': lambda q: np.exp(q*T),
}
rng=np.random.default_rng(2)
out=[]
for gn,g in G.items():
  for hn,h in H.items():
    best=None
    for t in range(60):
        p0=rng.uniform(0.2,3,2)
        def res(p):
            A=np.column_stack([TL, h(p[0])*g(p[1]), np.exp(-p[0]*0+0)*0+1*(np.ones_like(T))*0+np.exp(-3.0/T)*0+1]) if False else np.column_stack([TL, h(p[0])*g(p[1])])
            c=np.linalg.lstsq(A,sigma,rcond=None)[0]
            return sigma-A@c
        try:
            r=least_squares(res,p0,max_nfev=300)
        except Exception: continue
        if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
    if best is not None: out.append((np.mean(best.fun**2)/V,gn,hn,np.round(best.x,3)))
out.sort(key=lambda x:x[0])
